/**
 * Build OTel attribute maps without conditional spreads. `undefined` values
 * are dropped (the OTel API rejects them).
 */
export function attrs(input) {
    const out = {};
    for (const [key, value] of Object.entries(input)) {
        if (value !== undefined) {
            out[key] = value;
        }
    }
    return out;
}
